import { DomainError } from "./DomainError";
import { OrderStatus } from "./OrderStatus";

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
}

export class Order {
  private status: OrderStatus = "placed";
  private cancelled = false;

  public constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly lines: readonly OrderLine[],
  ) {
    if (!id.trim() || !customerId.trim() || lines.length === 0) {
      throw new DomainError("Order id, customer id, and at least one line are required");
    }
    for (const line of lines) {
      if (!line.productId.trim() || !Number.isInteger(line.quantity) || line.quantity <= 0) {
        throw new DomainError("Each order line needs a product and a positive integer quantity");
      }
    }
  }

  public get currentStatus(): OrderStatus {
    return this.status;
  }

  public get isCancelled(): boolean {
    return this.cancelled;
  }

  public advanceTo(nextStatus: OrderStatus): void {
    if (this.cancelled) {
      throw new DomainError("A cancelled order cannot be advanced");
    }
    const nextByStatus: Record<OrderStatus, OrderStatus | undefined> = {
      placed: "paid",
      paid: "packed",
      packed: "shipped",
      shipped: "delivered",
      delivered: undefined,
    };
    if (nextByStatus[this.status] !== nextStatus) {
      throw new DomainError(`Order cannot move from ${this.status} to ${nextStatus}`);
    }
    this.status = nextStatus;
  }

  public cancel(): void {
    if (this.cancelled) {
      throw new DomainError("Order is already cancelled");
    }
    if (this.status === "shipped" || this.status === "delivered") {
      throw new DomainError("A shipped order cannot be cancelled");
    }
    this.cancelled = true;
  }
}

